// Validates and normalises a lead posted to the intake webhook (for example by a scheduled research agent).
const item = $input.first().json;
const b = item.body || item;
const company = String(b.company || '').trim();
if (!company) return [{ json: { invalid: true } }];
const signals = Array.isArray(b.signals) ? b.signals.join('|') : String(b.signals || '');
const domain = String(b.domain || b.dominio || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
return [{ json: {
  invalid: false, company, role: b.role || b.rol || '', location: b.location || b.ubicacion || '', url: b.url || '', why: b.why || b.por_que || '',
  details: b.details || '', score: Number(b.score) || 0, domain, vertical: b.vertical || '', signals, employees: b.employees || b.empleados || ''
} }];

// Same company name or same domain already in the sheet: do not save it twice.
const lead = $('Parse intake lead').first().json;
if (lead.invalid) return [{ json: Object.assign({}, lead, { isDuplicate: false, skip: true }) }];
const norm = (s) => String(s || '').toLowerCase().replace(/&/g, ' and ').replace(/\b(inc|llc|ltd|corp|corporation|co|company|incorporated|holdings)\b/g, ' ').replace(/[^a-z0-9]+/g, '');
const nd = (d) => String(d || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const rows = $input.all();
const names = new Set(rows.map((r) => norm(r.json.Company)).filter(Boolean));
const domains = new Set(rows.map((r) => nd(r.json.Domain)).filter(Boolean));
const dup = (lead.domain && domains.has(nd(lead.domain))) || names.has(norm(lead.company));
return [{ json: Object.assign({}, lead, { isDuplicate: dup, skip: dup }) }];

// One item = one Adzuna call. The queries live in the Config node.
const C = $('Config (discovery)').first().json.cfg;
const A = (C.sources || {}).adzuna || {};
if (!A.enabled) return [];
return (A.queries || []).map((x) => ({ json: x }));

// Normalises Adzuna results to the common candidate shape and keeps only the job titles that matter for the ICP.
const C = $('Config (discovery)').first().json.cfg;
const A = (C.sources || {}).adzuna || {};
const keepRe = new RegExp(A.keep_regex || '.', 'i');
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const data = item.json || {};
  const results = Array.isArray(data.results) ? data.results : [];
  for (const r of results) {
    const title = r.title || '';
    if (!keepRe.test(title)) continue;
    const company = (r.company && r.company.display_name) ? r.company.display_name : '';
    if (!company) continue;
    const loc = (r.location && r.location.display_name) ? r.location.display_name : '';
    const key = `${company}|${title}`.toLowerCase().replace(/\s+/g, ' ').trim();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ json: {
      company, position: title, location: loc, url: r.redirect_url || '',
      description: `Company: ${company}. Location: ${loc}. ${(r.description || '').replace(/\s+/g, ' ').slice(0, 400)}`,
      dominio: '', source: 'adzuna', signals: ['hiring_sales_role'], created: r.created || ''
    } });
  }
}
return out;

// Google News RSS (free). Each query becomes one feed request.
const C = $('Config (discovery)').first().json.cfg;
const N = (C.sources || {}).news || {};
if (!N.enabled) return [];
return (N.queries || []).map((s) => ({ json: { url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(s) + '&hl=en-US&gl=US&ceid=US:en' } }));

// Extracts company + signal from headlines ("X raises $3M...", "X opens a new location...").
const C = $('Config (discovery)').first().json.cfg;
const N = (C.sources || {}).news || {};
const prefixes = (N.based_prefixes || []).filter(Boolean);
const basedRe = prefixes.length ? new RegExp('^(' + prefixes.join('|') + ')[- ]based\\s+', 'i') : null;
const STOP = new Set(['how', 'why', 'what', 'who', 'when', 'where', 'the', 'this', 'new', 'top', 'best', 'report', 'study'].concat(prefixes.map((p) => p.toLowerCase())));
const out = [];
const seen = new Set();
for (const it of $input.all()) {
  const j = it.json || {};
  const title = String(j.title || '').replace(/\s+-\s+[^-]{2,40}$/, '').trim();
  if (!title) continue;
  const pub = Date.parse(j.isoDate || j.pubDate || '');
  if (pub && Date.now() - pub > 45 * (24 * 3600 * 1000)) continue;
  const clean = basedRe ? title.replace(basedRe, '') : title;
  const m = clean.match(/^([A-Z0-9][\w&'.\-]*(?:\s+[A-Z0-9&][\w&'.\-]*){0,4}?)\s+(raises|raised|secures|secured|closes|closed|lands|announces|acquires|acquired|opens|opening|expands|expanding|launches|names|hires|appoints|adds)\b/);
  if (!m) continue;
  const company = m[1].trim();
  if (STOP.has(company.toLowerCase()) || company.split(/\s+/).length > 5) continue;
  const verb = m[2].toLowerCase();
  const signals = [];
  if (/raise|secure|close|land/.test(verb) && /\$|seed|series|funding|round/i.test(title)) signals.push('recent_funding');
  if (/open|expand/.test(verb)) signals.push('expansion');
  if (/acquire/.test(verb)) signals.push('acquisition');
  if (/name|hire|appoint|add/.test(verb) && /sales|revenue|business development|growth/i.test(title)) signals.push('new_sales_leader');
  if (!signals.length) continue;
  const key = company.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { company, position: '', location: N.location_label || '', url: j.link || '', description: 'News: ' + title, dominio: '', source: 'news', signals, vertical: '' } });
}
return out;

// "Weak" candidates (job ads + news) have no domain or firmographics yet. Here they are deduplicated, vacancy history is tracked
// (an old or repeated sales vacancy means the founder already tried and it did not stick), pre-scored, and capped before the
// paid company lookup (one Apollo credit each).
const C = $('Config (discovery)').first().json.cfg;
const normName = (s) => {
  const base = String(s || '').toLowerCase().replace(/&/g, ' and ');
  const stripped = base.replace(/\b(inc|llc|ltd|corp|corporation|co|company|incorporated|holdings)\b/g, ' ').replace(/[^a-z0-9]+/g, '');
  return stripped || base.replace(/[^a-z0-9]+/g, '');
};
const normDomain = (d) => String(d || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const uniq = (a) => Array.from(new Set((a || []).filter(Boolean)));
const BL = C.blocklists || {};
const words = (s) => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
const containsPhrase = (ws, term) => {
  const tw = words(term);
  if (tw.length === 0) return false;
  for (let i = 0; i <= ws.length - tw.length; i++) {
    let m = true;
    for (let j = 0; j < tw.length; j++) if (ws[i + j] !== tw[j]) { m = false; break; }
    if (m) return true;
  }
  return false;
};
// Competitors and vendors (whole word anywhere), big corporations (company name only), staffing firms and similar (substring).
const isBlocked = (company, description) => {
  const ws = words(company);
  const hay = `${company} ${description || ''}`.toLowerCase();
  const wset = new Set(words(hay));
  for (const t of (BL.whole_word || [])) if (wset.has(t)) return true;
  for (const t of (BL.big_corp || [])) if (containsPhrase(ws, t)) return true;
  for (const t of (BL.substring || [])) if (hay.includes(t)) return true;
  return false;
};
const W = (C.icp || {}).signal_weights || {};
const homeRe = (C.icp || {}).home_region_regex ? new RegExp(C.icp.home_region_regex, 'i') : null;
const preScore = (c) => {
  let s = 0;
  for (const sg of uniq(c.signals)) s += W[sg] || 0;
  if (homeRe && homeRe.test(c.location || '')) s += 1;
  return s;
};
const sd = $getWorkflowStaticData('global');
sd.seenWeak = sd.seenWeak || {};
sd.seenFinal = sd.seenFinal || {};
sd.jobHistory = sd.jobHistory || {};
const DAY = (24 * 3600 * 1000), NOW = Date.now();
for (const store of ['seenWeak', 'seenFinal']) {
  for (const k of Object.keys(sd[store])) if (NOW - sd[store][k].t > 45 * DAY) delete sd[store][k];
}
for (const k of Object.keys(sd.jobHistory)) if (NOW - (sd.jobHistory[k].last || 0) > 200 * DAY) delete sd.jobHistory[k];

const RESOLVE_CAP = (C.limits || {}).resolve_cap || 10;
const existingRows = $('Get existing leads').all();
const existingNames = new Set(existingRows.map((r) => normName(r.json.Company)).filter(Boolean));

const groups = new Map();
for (const it of $input.all()) {
  const j = it.json || {};
  const company = String(j.company || '').trim();
  if (!company) continue;
  const key = normName(company) || company.toLowerCase();
  let g = groups.get(key);
  if (!g) {
    g = Object.assign({}, j, { company, key, signals: [].concat(j.signals || []), sources: [j.source].filter(Boolean), positions: j.position ? [j.position] : [] });
    groups.set(key, g);
  } else {
    g.signals.push(...[].concat(j.signals || []));
    if (j.source && !g.sources.includes(j.source)) g.sources.push(j.source);
    if (j.position && !g.positions.includes(j.position)) g.positions.push(j.position);
    if (!g.url && j.url) g.url = j.url;
    if (!g.created && j.created) g.created = j.created;
    if (String(j.description || '').length > String(g.description || '').length) g.description = j.description;
  }
}

const picked = [];
for (const [key, g] of groups) {
  if (g.sources.includes('adzuna') && g.positions.length) {
    const h = sd.jobHistory[key] || { first: NOW, titles: [] };
    for (const p of g.positions) { const t = String(p).toLowerCase().trim(); if (!h.titles.includes(t)) h.titles.push(t); }
    h.last = NOW;
    sd.jobHistory[key] = h;
    const createdAge = g.created ? (NOW - Date.parse(g.created)) / DAY : 0;
    const histAge = (NOW - h.first) / DAY;
    if (Math.max(createdAge, histAge) >= 30) g.signals.push('stale_vacancy');
    if (histAge >= 45 && h.titles.length >= 2) g.signals.push('repeat_sales_hiring');
  }
  g.signals = uniq(g.signals);
  if (existingNames.has(key)) continue;
  if (isBlocked(g.company, g.description)) continue;
  const sig = g.signals.slice().sort().join('|');
  const prev = sd.seenWeak[key];
  if (prev && NOW - prev.t < 14 * DAY && prev.sig === sig) continue;
  g.pre = preScore(g);
  picked.push(g);
}
picked.sort((a, b) => b.pre - a.pre);
const top = picked.slice(0, RESOLVE_CAP);
for (const g of top) sd.seenWeak[g.key] = { t: NOW, sig: g.signals.slice().sort().join('|') };

return top.map((g) => ({ json: {
  company: g.company, position: g.positions.join(' / ') || g.position || '', location: g.location || '', url: g.url || '',
  description: g.description || '', dominio: '', source: g.sources.join('+'), signals: g.signals, vertical: g.vertical || '', created: g.created || ''
} }));

// Joins the Apollo lookup (one organisation per candidate, same order) back to the original candidate.
const base = $('Prepare weak candidates').all();
const tokens = (s) => String(s || '').toLowerCase().replace(/&/g, ' and ').replace(/\b(inc|llc|ltd|corp|corporation|co|company|incorporated|holdings|the)\b/g, ' ').split(/[^a-z0-9]+/).filter(Boolean);
const similar = (a, b) => {
  const ta = tokens(a), tb = tokens(b);
  if (!ta.length || !tb.length) return false;
  const sa = ta.join(''), sb = tb.join('');
  if (sa === sb) return true;
  if (Math.min(sa.length, sb.length) >= 5 && (sa.includes(sb) || sb.includes(sa))) return true;
  const A = new Set(ta), B = new Set(tb);
  let inter = 0; for (const t of A) if (B.has(t)) inter++;
  return inter / (A.size + B.size - inter) >= 0.6;
};
const hostOf = (u) => String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const out = [];
$input.all().forEach((item, i) => {
  const c = base[i] && base[i].json;
  if (!c) return;
  const data = item.json || {};
  const orgs = [].concat(data.organizations || [], data.accounts || []);
  const o = orgs[0] || null;
  const res = Object.assign({}, c, { signals: [].concat(c.signals || []) });
  if (o && o.name && similar(o.name, c.company)) {
    res.dominio = o.primary_domain || o.domain || hostOf(o.website_url) || '';
    res.empleados = o.estimated_num_employees || '';
    res.revenue = o.organization_revenue || o.organization_revenue_printed || '';
    const fDate = o.latest_funding_round_date || o.latest_funding_date || '';
    const fStage = o.latest_funding_stage || '';
    res.funding = [fStage, fDate ? String(fDate).slice(0, 10) : ''].filter(Boolean).join(' ');
    if (fDate && (Date.now() - Date.parse(fDate)) < 365 * (24 * 3600 * 1000)) res.signals.push('recent_funding');
    const kw = Array.isArray(o.keywords) ? o.keywords.slice(0, 8).join(', ') : '';
    res.description = [res.description, o.short_description, kw ? 'Keywords: ' + kw : ''].filter(Boolean).join(' ').slice(0, 900);
    res.resolved = true;
  } else {
    res.resolved = false;
    // A news item whose company cannot be confirmed is noise and is dropped. A job ad still goes through (the LLM judges it).
    if (String(c.source || '').includes('news')) return;
  }
  out.push({ json: res });
});
return out;

// Company searches by firmographics + signal. The page rotates daily so the same companies do not come back every run.
const C = $('Config (discovery)').first().json.cfg;
const A = (C.sources || {}).apollo || {};
if (!A.enabled) return [];
const day = Math.floor(Date.now() / (24 * 3600 * 1000));
const page = (day % (A.rotate_pages || 4)) + 1;
const ago = (d) => new Date(Date.now() - d * (24 * 3600 * 1000)).toISOString().slice(0, 10);
const base = { organization_locations: A.locations || [], page, per_page: 50 };
return (A.queries || []).map((q) => {
  const body = Object.assign({}, base, { q_organization_keyword_tags: q.keywords || [], organization_num_employees_ranges: q.employee_ranges || [] });
  if (q.job_titles) {
    body.q_organization_job_titles = q.job_titles === 'sales_titles' ? (A.sales_titles || []) : q.job_titles;
    body.organization_job_posted_at_range = { min: ago(q.job_posted_days || 60) };
  }
  if (q.funding_days) body.latest_funding_date_range = { min: ago(q.funding_days) };
  return { json: { vertical: q.vertical, label: q.label, signals: q.signals || [], body } };
});

// Normalises Apollo company results (one response per query, same order) to the common candidate shape.
const queries = $('Build Apollo queries').all();
const hostOf = (u) => String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const out = [];
$input.all().forEach((item, i) => {
  const q = (queries[i] && queries[i].json) || {};
  const data = item.json || {};
  const orgs = [].concat(data.organizations || [], data.accounts || []);
  for (const o of orgs) {
    const name = o.name;
    if (!name) continue;
    const signals = [].concat(q.signals || []);
    const fDate = o.latest_funding_round_date || o.latest_funding_date || '';
    if (fDate && (Date.now() - Date.parse(fDate)) < 365 * (24 * 3600 * 1000)) signals.push('recent_funding');
    const kw = Array.isArray(o.keywords) ? o.keywords.slice(0, 8).join(', ') : '';
    out.push({ json: {
      company: name,
      position: (q.signals || []).some((s) => /hiring/.test(s)) ? 'Open sales vacancy (per Apollo)' : '',
      location: [o.city, o.state].filter(Boolean).join(', ') || o.raw_address || '',
      url: o.linkedin_url || o.website_url || '',
      description: [o.short_description, kw ? 'Keywords: ' + kw : ''].filter(Boolean).join(' ').slice(0, 900),
      dominio: o.primary_domain || o.domain || hostOf(o.website_url) || '',
      source: 'apollo', signals, vertical: q.vertical || '',
      empleados: o.estimated_num_employees || '',
      revenue: o.organization_revenue || o.organization_revenue_printed || '',
      funding: [o.latest_funding_stage, fDate ? String(fDate).slice(0, 10) : ''].filter(Boolean).join(' ')
    } });
  }
});
return out;

// Merges every source by domain (or name), stacks the signals, computes the rule-based ICP matrix (0-12) and lets only the
// best candidates through to the LLM. Already-known companies and recently evaluated ones with no new signal are skipped.
const C = $('Config (discovery)').first().json.cfg;
const normName = (s) => {
  const base = String(s || '').toLowerCase().replace(/&/g, ' and ');
  const stripped = base.replace(/\b(inc|llc|ltd|corp|corporation|co|company|incorporated|holdings)\b/g, ' ').replace(/[^a-z0-9]+/g, '');
  return stripped || base.replace(/[^a-z0-9]+/g, '');
};
const normDomain = (d) => String(d || '').toLowerCase().trim().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const uniq = (a) => Array.from(new Set((a || []).filter(Boolean)));
const BL = C.blocklists || {};
const words = (s) => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
const containsPhrase = (ws, term) => {
  const tw = words(term);
  if (tw.length === 0) return false;
  for (let i = 0; i <= ws.length - tw.length; i++) {
    let m = true;
    for (let j = 0; j < tw.length; j++) if (ws[i + j] !== tw[j]) { m = false; break; }
    if (m) return true;
  }
  return false;
};
// Competitors and vendors (whole word anywhere), big corporations (company name only), staffing firms and similar (substring).
const isBlocked = (company, description) => {
  const ws = words(company);
  const hay = `${company} ${description || ''}`.toLowerCase();
  const wset = new Set(words(hay));
  for (const t of (BL.whole_word || [])) if (wset.has(t)) return true;
  for (const t of (BL.big_corp || [])) if (containsPhrase(ws, t)) return true;
  for (const t of (BL.substring || [])) if (hay.includes(t)) return true;
  return false;
};
const W = (C.icp || {}).signal_weights || {};
const homeRe = (C.icp || {}).home_region_regex ? new RegExp(C.icp.home_region_regex, 'i') : null;
const preScore = (c) => {
  let s = 0;
  for (const sg of uniq(c.signals)) s += W[sg] || 0;
  if (homeRe && homeRe.test(c.location || '')) s += 1;
  return s;
};
const sd = $getWorkflowStaticData('global');
sd.seenWeak = sd.seenWeak || {};
sd.seenFinal = sd.seenFinal || {};
sd.jobHistory = sd.jobHistory || {};
const DAY = (24 * 3600 * 1000), NOW = Date.now();
for (const store of ['seenWeak', 'seenFinal']) {
  for (const k of Object.keys(sd[store])) if (NOW - sd[store][k].t > 45 * DAY) delete sd[store][k];
}
for (const k of Object.keys(sd.jobHistory)) if (NOW - (sd.jobHistory[k].last || 0) > 200 * DAY) delete sd.jobHistory[k];

const LLM_CAP = (C.limits || {}).llm_cap || 25;
const MAX_EMP = (C.limits || {}).max_employees || 100;
const ICP = C.icp || {};
const R = ICP.revenue_ideal || [500000, 5000000];
const E = ICP.employees_ok || [3, 30];
const parseRevenue = (r) => {
  if (typeof r === 'number') return r;
  const m = String(r || '').replace(/,/g, '').match(/([\d.]+)\s*([kmb])?/i);
  if (!m) return 0;
  const n = parseFloat(m[1]); if (!isFinite(n)) return 0;
  const mult = { k: 1e3, m: 1e6, b: 1e9 }[(m[2] || '').toLowerCase()] || 1;
  return n * mult;
};
// ICP readiness matrix: 6 criteria x 0-2 = 0-12. It only scores what the system can actually know.
const matrixScore = (c) => {
  const sg = new Set(c.signals || []);
  const emp = Number(c.empleados) || 0;
  const rev = Number(c.revenue_num) || 0;
  const p = {};
  p.founder = sg.has('founder_closing') ? 2 : (emp > 0 && emp <= (ICP.founder_led_max_employees || 15) ? 1 : 0);
  p.revenue = (rev >= R[0] && rev <= R[1]) ? 2 : (rev > R[1] ? (rev <= R[1] * 2 ? 1 : 0) : (emp >= E[0] && emp <= E[1] ? 1 : 0));
  p.growth = (sg.has('hiring_sales_role') || sg.has('hiring_sales_manager') || sg.has('recent_funding') || sg.has('expansion')) ? 2 : ((sg.has('acquisition') || sg.has('new_sales_leader')) ? 1 : 0);
  p.tried = (sg.has('repeat_sales_hiring') || sg.has('stale_vacancy')) ? 2 : ((sg.has('referral_dependent') || sg.has('crm_spreadsheets')) ? 1 : 0);
  p.reachable = c.dominio ? 1 : 0;
  p.urgency = (sg.has('recent_funding') || sg.has('expansion') || sg.has('stale_vacancy')) ? 2 : ((sg.has('hiring_sales_role') || sg.has('hiring_sales_manager')) ? 1 : 0);
  const total = Object.values(p).reduce((a, b) => a + b, 0);
  return { total, detail: Object.entries(p).map(([k, v]) => k + ':' + v).join(' ') };
};

const existingRows = $('Get existing leads').all();
const existingNames = new Set(existingRows.map((r) => normName(r.json.Company)).filter(Boolean));
const existingDomains = new Set(existingRows.map((r) => normDomain(r.json.Domain)).filter(Boolean));

const byDomain = new Map(), byName = new Map(), groups = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const company = String(j.company || '').trim();
  if (!company) continue;
  const dk = normDomain(j.dominio);
  const nk = normName(company) || company.toLowerCase();
  const sigs = [].concat(j.signals || []);
  const srcs = String(j.source || '').split('+').filter(Boolean);
  let g = (dk && byDomain.get(dk)) || byName.get(nk);
  if (!g) {
    g = { company, positions: j.position ? [j.position] : [], location: j.location || '', url: j.url || '', description: j.description || '',
      dominio: dk, sources: srcs, signals: sigs, vertical: j.vertical || '', empleados: j.empleados || '', revenue: j.revenue || '', funding: j.funding || '' };
    groups.push(g);
  } else {
    g.sources.push(...srcs); g.signals.push(...sigs);
    if (j.position && !g.positions.includes(j.position)) g.positions.push(j.position);
    if (!g.dominio && dk) g.dominio = dk;
    if (!g.url && j.url) g.url = j.url;
    if (!g.location && j.location) g.location = j.location;
    if (!g.vertical && j.vertical) g.vertical = j.vertical;
    if (!g.empleados && j.empleados) g.empleados = j.empleados;
    if (!g.revenue && j.revenue) g.revenue = j.revenue;
    if (!g.funding && j.funding) g.funding = j.funding;
    if (String(j.description || '').length > String(g.description || '').length) g.description = j.description;
  }
  if (dk) byDomain.set(dk, g);
  byName.set(nk, g);
}

const out = [];
for (const g of groups) {
  g.signals = uniq(g.signals); g.sources = uniq(g.sources);
  const nk = normName(g.company);
  if (existingNames.has(nk) || (g.dominio && existingDomains.has(g.dominio))) continue;
  if (isBlocked(g.company, g.description)) continue;
  if ((Number(g.empleados) || 0) > MAX_EMP) continue;           // out of ICP by size
