  String(j.Status || '').trim().toLowerCase() === 'sent' && String(j.Sent_on || '').trim() !== '' &&
  String(j.Followup_on || '').trim() === '' && String(j.Reply_text || '').trim() === '' && String(j.Interest || '').trim() === '' &&
  String(j.Contact_email || '').trim() !== '' && bizDays(j.Sent_on) >= (F.after_business_days || 3));
if (!eligible.length) return [];
const j = eligible[0];
const fill = (tpl, v) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));
const v = { name: j.Contact_name || '', title: j.Contact_title || '', company: j.Company, why: j.Why || '', role: j.Role || '', details: j.Details || '',
  sender_name: C.sender.name, sender_title: C.sender.title, sender_company: C.sender.company, signature: C.sender.signature };
return [{ json: {
  row_number: j.row_number, company: j.Company, contact_name: j.Contact_name || '', contact_email: j.Contact_email,
  followup_request: { model: C.models.followup, stream: false, format: 'json', think: false, keep_alive: '15m',
    options: { temperature: 0.4, num_ctx: 4096 }, messages: [{ role: 'user', content: fill(F.prompt, v) }] }
} }];

// Reads the follow-up draft. If the model fails the draft says so, so a human writes it instead.
const prev = $('Pick follow-up').first().json;
let p = null;
try { p = JSON.parse($input.first().json.message.content); } catch (e) { p = null; }
const subject = (p && p.subject) || ('Re: ' + prev.company);
const body = (p && p.body) || 'The follow-up could not be generated automatically. Write it by hand.';
const out = Object.assign({}, prev, { followup_subject: subject, followup_body: String(body).replace(/\n/g, '<br>') });
delete out.followup_request;
return [{ json: out }];

