// Weekly funnel: which source, signal and vertical converts best (leads > contacted > replies > interested).
const C = $('Config (report)').first().json.cfg;
const rows = $input.all().map((r) => r.json).filter((r) => String(r.Company || '').trim());
const isSent = (r) => ['sent', 'replied'].includes(String(r.Status || '').trim().toLowerCase()) || String(r.Sent_on || '').trim() !== '';
const replied = (r) => String(r.Reply_text || '').trim() !== '';
const interested = (r) => String(r.Interest || '').trim().toLowerCase() === 'yes';
const agg = (keyFn) => {
  const m = new Map();
  for (const r of rows) {
    for (const k of keyFn(r)) {
      const a = m.get(k) || { leads: 0, sent: 0, replied: 0, interested: 0, score: 0 };
      a.leads++; a.score += Number(r.Score) || 0;
      if (isSent(r)) a.sent++;
      if (replied(r)) a.replied++;
      if (interested(r)) a.interested++;
      m.set(k, a);
    }
  }
  return Array.from(m.entries()).sort((x, y) => y[1].leads - x[1].leads);
};
const pct = (n, d) => d ? Math.round(100 * n / d) + '%' : '-';
const table = (title, entries) => {
  const body = entries.map(([k, a]) => `<tr><td>${k}</td><td>${a.leads}</td><td>${(a.score / a.leads).toFixed(1)}</td><td>${a.sent}</td><td>${a.replied}</td><td>${pct(a.replied, a.sent)}</td><td>${a.interested}</td></tr>`).join('');
  return `<h3>${title}</h3><table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px"><tr><th>${title}</th><th>Leads</th><th>Avg score</th><th>Contacted</th><th>Replies</th><th>Reply rate</th><th>Interested</th></tr>${body}</table>`;
};
const weekAgo = Date.now() - 7 * (24 * 3600 * 1000);
const newThisWeek = rows.filter((r) => Date.parse(r.Added_on) >= weekAgo).length;
const bySource = agg((r) => [String(r.Source || '').trim() || '(no source)']);
const bySignal = agg((r) => { const s = String(r.Signals || '').split('|').map((x) => x.trim()).filter(Boolean); return s.length ? s : ['(no signals)']; });
const byVertical = agg((r) => [String(r.Vertical || '').trim() || '(no vertical)']);
const html = `<h2>${C.report_title}</h2><p>Leads in the pool: <b>${rows.length}</b>. New this week: <b>${newThisWeek}</b>. Contacted: <b>${rows.filter(isSent).length}</b>. Replies: <b>${rows.filter(replied).length}</b>. Interested: <b>${rows.filter(interested).length}</b>.</p>` +
  table('Source', bySource) + table('Signal', bySignal) + table('Vertical', byVertical) +
  '<p style="color:#666;font-size:12px">Reply rate = replies / contacted. With few contacted leads per row, read it as a trend, not a conclusion.</p>';
return [{ json: { subject: C.report_title, html } }];
